# Generated by build.py from recipe.yml for recipe http-tell-a-clean-close-from-a-reset. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'dl', 'site' | Out-Null
cmd /c 'openssl rand -out site/big.bin 2000000'
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', 'http://127.0.0.1:8080/', 'http://127.0.0.1:8081/', '--fault', '"drop;listener=http://127.0.0.1:8080/;after-bytes=1000000;close=graceful"', '--fault', '"drop;listener=http://127.0.0.1:8081/;after-bytes=1000000"' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --max-time 30 -o dl/clean.bin -w "%{http_code} %{size_header} %{size_download}\n" http://127.0.0.1:8080/big.bin } finally { Stop-Process $server0 }
